CREATE TABLE repos(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, url TEXT, local_path TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE scans(id INTEGER PRIMARY KEY, repo_id INTEGER NOT NULL, commit_sha TEXT, scanner_version TEXT NOT NULL, rules_version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error_message TEXT, started_at TEXT DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, CHECK (status IN ('pending', 'scanned', 'scored', 'triaged', 'planned', 'failed')), FOREIGN KEY (repo_id) REFERENCES repos(id));
CREATE TABLE files(id INTEGER PRIMARY KEY, scan_id INTEGER NOT NULL, path TEXT NOT NULL, language TEXT NOT NULL, is_test_path INTEGER NOT NULL, is_doc_path INTEGER NOT NULL, UNIQUE (scan_id, path), CHECK (is_doc_path IN (0,1)), CHECK (is_test_path IN (0,1)), FOREIGN KEY (scan_id) REFERENCES scans(id));
CREATE TABLE findings(id INTEGER PRIMARY KEY, file_id INTEGER NOT NULL, fingerprint TEXT NOT NULL, line INTEGER NOT NULL, detection_rule_code TEXT NOT NULL, detection_method TEXT NOT NULL, primitive TEXT NOT NULL, operation TEXT NOT NULL, key_size INTEGER, curve TEXT, confidence TEXT NOT NULL, snippet TEXT, UNIQUE (file_id, fingerprint), CHECK (detection_method IN ('ast', 'dependency', 'text')), CHECK (confidence IN ('high', 'medium', 'low')), FOREIGN KEY (file_id) REFERENCES files(id));